const config = require('./base.js').config;
const pj = require('../package.json');
const packageName = pj.name;

config.capabilities = [
    {
        browserName: 'chrome',
        maxInstances: 1,
        'goog:chromeOptions': {
            // to run chrome headless the following flags are required
            // (see https://developers.google.com/web/updates/2017/04/headless-chrome)
            args: ['--window-size=1280,720', '--disable-gpu', '--no-sandbox', '--headless'],
        },
    },
];

if (packageName.endsWith('/x3-automatedtestplatform'))
    config.capabilities[0]['goog:chromeOptions']['args'].push('--lang=en-GB');

exports.config = config;
